window.AUTH=window.AUTH||{};window.AUTH["06-9130"]={"d":"06-9130","id":"2007/06-9130","n":"Ali v. Federal Bureau of Prisons","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the respondents","date":"","url":"https://www.justice.gov/osg/media/200746/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/ali-v-federal-bureau-prisons-brief-merits","n":109}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep552/usrep552214/usrep552214.pdf","tr":true,"items":[{"t":"case","label":"ABC v. DEF","cite":"2007 WL 2500738","y":2007,"court":"2d Cir. Sept. 5","by":{"0":"38"}},{"t":"case","label":"Agunbiade v. Federal Bureau of Prisons","cite":"52 Fed. Appx. 492","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./52/492/","by":{"0":"4"}},{"t":"case","label":"Ali v. United States","cite":"581 A.2d 368","y":1990,"court":"D.C.","url":"https://www.courtlistener.com/c/A.2d/581/368/","by":{"0":"3"}},{"t":"case","label":"Bazuaye v. United States","cite":"83 F.3d 482","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/83/482/","op":2,"sum":"Explaining that “[a]ny attempt to parse this report suffers from the same interpretative problem plaguing § 2680(c) itself”.","sumSrc":"brief:0","by":{"0":"11, 33, 39"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Fed. Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Bramwell v. United States Bureau of Prisons","cite":"348 F.3d 804","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/348/804/","op":1,"by":{"0":"38"}},{"t":"case","label":"Chapa v. United States Dep’t of Justice","cite":"339 F.3d 388","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/339/388/","op":1,"sum":"Holding that BOP officials “detained” prisoner’s property when they inspected and then shipped it during an inter-prison transfer.","sumSrc":"brief:0","by":{"0":"15"}},{"t":"case","label":"Cheney v. United States","cite":"972 F.2d 247","y":1992,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/972/247/","op":1,"by":{"0":"39"}},{"t":"case","label":"Circuit City Stores, Inc. v. Adams","cite":"532 U.S. 105","y":2001,"id":"2000/99-1379","sc":1,"op":7,"ar":7,"sum":"Construing “any other class of workers engaged in . . . commerce,” 9 U. S. C. § 1, narrowly based on the Court’s previous interpretation of “in commerce” as a term of art with a narrower meaning.","sumSrc":"opinion","by":{"0":"17, 27, 30"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 30"}},{"t":"case","label":"CPSC v. GTE Sylvania, Inc.","cite":"447 U.S. 102","y":1980,"id":"1979/79-521","sc":1,"sum":"Section 6 (b) (1) governs the disclosure of records by the Commission pursuant to a request under the FOIA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"op":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Formula One Motors, Ltd. v. United States","cite":"777 F.2d 822","y":1985,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/777/822/","op":3,"ar":2,"sum":"Holding that the seizure of a vehicle still in transit from overseas by DEA agents who searched it for drugs was “sufﬁciently akin to the functions carried out by Customs ofﬁ­ cials to place the agents’ conduct within the scope of section 2680(c)”.","sumSrc":"opinion","by":{"0":"24, 25"}},{"t":"case","label":"Fort Stewart Sch. v. FLRA","cite":"495 U.S. 641","y":1990,"id":"1989/89-65","sc":1,"op":1,"sum":"Noting that “technically unneces­ sary” examples may have been “inserted out of an abundance of caution”.","sumSrc":"opinion","by":{"0":"27"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Gutierrez v. Ada","cite":"528 U.S. 250","y":2000,"id":"1999/99-51","sc":1,"op":4,"sum":"The Court held that \"[t]he Guam Organic Act does not require a runoff election when a candidate slate has received a majority of the votes cast for Governor and Lieutenant Governor of the Territory, but not a majority of the number of ballots cast in the simultaneous general election.\" Justice Souter wrote for the Court that an \"obvious reading\" of the law requires only a majority of votes cast in that one specific race, \"Congress did not shift its attention when it used 'any election' unadorned by a gubernatorial reference or other definite modifier.\".","sumSrc":"Oyez","by":{"0":"22, 23"}},{"t":"case","label":"Gutierrez de Martinez v. Lamagno","cite":"515 U.S. 417","y":1995,"id":"1994/94-167","sc":1,"sum":"Invoking the federal court's jurisdiction based on diversity of citizenship, petitioners alleged in their complaint that they had suffered physical injuries and property damage as a result of an accident in Colombia caused by the negligence of respondent Lamagno, a federal employee. The United States Attorney, acting pursuant to the statute commonly known as the Westfall Act, 28 U. S. C. §2679(d)(1), certified on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Halverson v. United States","cite":"972 F.2d 654","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/972/654/","by":{"0":"11"}},{"t":"case","label":"Hartford Underwriters Ins. Co. v. Union Planters Bank, N.A.","cite":"530 U.S. 1","y":2000,"id":"1999/99-409","sc":1,"sum":"The Court held that \"Section 506(c) does not provide an administrative claimant of a bankruptcy estate an independent right to seek payment of its claim from property encumbered by a secured creditor's lien, or subject to secured claims.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"Harrison v. PPG Indus., Inc.","cite":"446 U.S. 578","y":1980,"id":"1979/78-1918","sc":1,"op":3,"ar":1,"sum":"Rejecting an argument that ejusdem generis must apply when a broad interpretation of the clause could render the speciﬁc enumer­ ations unnecessary.","sumSrc":"opinion","by":{"0":"17, 26, 36"}},{"t":"case","label":"Hatzlachh Supply Co. v. United States","cite":"444 U.S. 460","y":1980,"id":"1979/78-1175","sc":1,"ar":1,"sum":"The United States may be held liable in an action under the Tucker Act for breach of an implied contract of bailment when goods are lost while held by the United States Customs Service following their seizure for customs violations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Helvering v. Stockholms Enskilda Bank","cite":"293 U.S. 84","y":1934,"id":"scdb/1934-037","sc":1,"sum":"Assistant Solicitor General MacLean, with whom Solicitor General Biggs, Assistant Attorney General Wideman, and Messrs. James W. Morris, John H. McEvers, and W. Marvin Smith were on the brief, for petitioner.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Holder v. Hall","cite":"512 U.S. 874","y":1994,"id":"1993/91-2012","sc":1,"sum":"The judgment is reversed, and the case is remanded. 955 F. 2d 1563, reversed and remanded. JUSTICE KENNEDY, joined by THE CHIEF JUSTICE and JUSTICE O'CONNOR, concluded in Parts I, II-A, and III:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Hughes Aircraft Co. v. Jacobson","cite":"525 U.S. 432","y":1999,"id":"1998/97-1287","sc":1,"sum":"The Court held Hughes did not violate the ERISA by establishing an early retirement program and creating a noncontributory benefit structure for new participants. Justice Thomas, writing for the Court, said the plan amendments \"did not affect the rights of pre-existing plan participants and Hughes did not use the surplus for its own benefit.\".","sumSrc":"Oyez","by":{"0":"9"}},{"t":"case","label":"International Bhd. of Teamsters v. United States","cite":"431 U.S. 324","y":1977,"id":"1976/75-636","sc":1,"op":1,"sum":"The United States instituted this litigation under Title VII of the Civil Rights Act of 1964 against petitioners, a nationwide common carrier of motor freight, and a union representing a large group of the company's employees. The Government alleged that the company had engaged in a pattern or practice of discriminating against Negroes and Spanishsurnamed persons (hereinafter sometimes collectively \"minority …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"James v. United States","cite":"127 S. Ct. 1586","y":2007,"id":"2006/05-9264","sc":1,"sum":"The Court ruled 5-3 that attempted burglary is a \"violent felony\" for purposes of the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"0":"17, 18, 20, 21"}},{"t":"case","label":"Jefferson County Pharm. Ass’n v. Abbott Labs.","cite":"460 U.S. 150","y":1983,"id":"1982/81-827","sc":1,"sum":"The sale of pharmaceutical products to state and local government hospitals for resale in competition with private pharmacies is not exempt from the Act's proscriptions.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Jones v. Bock","cite":"127 S. Ct. 910","y":2007,"id":"2006/05-7058","sc":1,"ar":1,"sum":"The Court ruled unanimously that the Sixth Circuit's rules for exhaustion of administrative remedies were not required by the Prisoner Litigation Reform Act. The opinion by Chief Justice John Roberts held that prisoners bring civil rights lawsuits do not need to demonstrate that they have already exhausted all administrative remedies.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Jones v. Simpson","cite":"116 U.S. 609","y":1886,"id":"scdb/1885-137","sc":1,"sum":"A sale of -personal property made by the. vendor with intent to defraud his creditors, but for valuable consideration paid to him by the vendee, followed by actual and continued change of possession, is Valid against the vendor’s creditors, unless it also appears that the vendee acted in bad faith. This rule prevails in Kansas,","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Kosak v. United States","cite":"465 U.S. 848","y":1984,"id":"1983/82-618","sc":1,"op":6,"ar":6,"sum":"Holding that “detention” encompasses claims resulting from negligent handling or storage.","sumSrc":"opinion","by":{"0":"passim"}},{"t":"case","label":"Kurinsky v. United States","cite":"33 F.3d 594","y":1994,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/33/594/","op":1,"by":{"0":"11, 39"}},{"t":"case","label":"Mackey v. Lanier Collection Agency & Serv., Inc.","cite":"486 U.S. 825","y":1988,"id":"1987/86-1387","sc":1,"sum":"After respondent collection agency obtained money judgments against participants in an \"employee welfare benefit plan\" covered by the Employee Retirement Income Security Act of 1974 (ERISA), its request to garnish the debtors' plan benefits was granted by a Georgia trial court. The State Court of Appeals reversed, holding that Ga. Code Ann. § 18-4-22.1 (1982), barring the garnishment of \"[flunds or benefits of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Maine v. Thiboutot","cite":"448 U.S. 1","y":1980,"id":"1979/79-838","sc":1,"by":{"0":"17"}},{"t":"case","label":"Norfolk & W. Ry. v. American Train Dispatchers Ass’n","cite":"499 U.S. 117","y":1991,"id":"1990/89-1027","sc":1,"op":3,"ar":1,"sum":"Noting that interpre­ tive canons must yield “when the whole context dictates a different conclusion”.","sumSrc":"opinion","by":{"0":"17"}},{"t":"case","label":"Oscar Mayer & Co. v. Evans","cite":"441 U.S. 750","y":1979,"id":"1978/78-275","sc":1,"sum":"Section 14 (b) of the Age Discrimination in Employment Act of 1967 (ADEA) provides that in the case of an alleged unlawful practice occurring in a State which has a law prohibiting discrimination in employment because of age and authorizing a state authority to grant and seek relief from such discriminatory practice, no suit may be brought under § 7 (c) of the ADEA before the expiration of 60 days after proceedings …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"PBGC v. LTV Corp.","cite":"496 U.S. 633","y":1990,"id":"1989/89-390","sc":1,"sum":"The PBGC's restoration decision was not arbitrary and capricious or contrary to law under § 706(2)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Pennsylvania Dep’t of Corr. v. Yeskey","cite":"524 U.S. 206","y":1998,"id":"1997/97-634","sc":1,"sum":"The Court held that under the ADA no \"public entity\" may discriminate against qualified disabled individuals due to their disability. Moreover, the Court stated that the ADA's protections extended to cover prison inmates as well as any other liberated citizen.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Red Lion Broad Co. v. FCC","cite":"395 U.S. 367","y":1969,"id":"1968/2","sc":1,"sum":"The Court held that the fairness doctrine was consistent with the First Amendment.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Russell Motor Car Co. v. United States","cite":"261 U.S. 514","y":1923,"id":"scdb/1922-150","sc":1,"sum":"(a) The word “material” included anti-aircraft gun-mounts for the Navy.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Schlaebitz v. United States Dep’t of Justice","cite":"924 F.2d 193","y":1991,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/924/193/","op":1,"sum":"Holding that United States Mar­ shals, who were allegedly negligent in releasing a parolee’s luggage to a third party, were “law enforcement ofﬁcers” under § 2680(c).","sumSrc":"opinion","by":{"0":"5"}},{"t":"case","label":"S.D. Warren & Co. v. Maine Bd. of Envtl. Prot.","cite":"126 S. Ct. 1843","y":2006,"id":"2005/04-1527","sc":1,"op":1,"sum":"The Supreme Court held that the term \"discharge\" in section 401 had historically been given a broad meaning by FERC, the Environmental Protection Agency, and even the Supreme Court. Justice David Souter, in the Opinion of the Court, wrote that \"[w]hen it applies to water, 'discharge' commonly means a 'flowing or issuing out.' .","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Sonnenthiel v. Christian Moerlein Brewing Co.","cite":"172 U.S. 401","y":1899,"id":"scdb/1898-044","sc":1,"sum":"A suit against a marshal of the United States, for acts done in his official capacity, is a suit arising under the laws of the United States; and the joinder of another defendant, jurisdiction over whom is dependent upon diversity of citizenship, does not deprive the.marshal of rights he would otherwise possess.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"0":"9"}},{"t":"case","label":"Taylor v. United States","cite":"550 F.2d 983","y":1977,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/550/983/","sum":"Stating that, when a customs officer seized drugs at the border, he was “acting to enforce the drug law’s prohibition against importation, not to enforce an independent rule of the customs law”.","sumSrc":"brief:0","by":{"0":"25"}},{"t":"case","label":"United Air Lines, Inc. v. McCann","cite":"434 U.S. 192","y":1977,"id":"1977/76-906","sc":1,"sum":"Petitioner's retirement plan comes within the § 4 (f) (2) exception, in the context of which \"subterfuge\" must be given its ordinary meaning as a scheme or stratagem to avoid the application of the Act. There is nothing to suggest that Congress intended to invalidate plans that were instituted m good faith before the Act's passage or that it intended to require employers to show a business or economic purpose to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"United States v. Aguilar","cite":"515 U.S. 593","y":1995,"id":"1994/94-270","sc":1,"op":1,"sum":"Rejecting the canon’s applicability to an omnibus clause that was “one of . . . several distinct and independent prohibi­ tions” rather than “a general or collective term following a list of speciﬁc items to which a particular statutory command is applicable”.","sumSrc":"opinion","by":{"0":"18"}},{"t":"case","label":"United States v. Estate of Romani","cite":"523 U.S. 517","y":1998,"id":"1997/96-1613","sc":1,"sum":"The Court held that section 3713(a) does not require that a federal tax claim be given preference over a judgment creditor's perfected lien on real property.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"op":3,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"0":"9, 16"}},{"t":"case","label":"United States v. Lockheed L-188 Aircraft","cite":"656 F.2d 390","y":1979,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/656/390/","by":{"0":"11, 39"}},{"t":"case","label":"United States v. Monsanto","cite":"491 U.S. 600","y":1989,"id":"1988/88-454","sc":1,"sum":"Respondent, who allegedly directed a large-scale heroin distribution enterprise, was indicted for alleged violations of racketeering laws, creation of a continuing criminal enterprise, and tax and firearm offenses. The indictment also alleged that respondent had accumulated three specified assets as a result of his narcotics trafficking, which were subject to forfeiture under the Comprehensive Forfeiture Act of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"United States v. Muniz","cite":"374 U.S. 150","y":1963,"id":"1962/464","sc":1,"sum":"A federal prisoner can sue under the Federal Tort Claims Act to recover damages from the United States for personal injuries sustained during confinement in a federal prison and resulting from the negligence of a government employee. Feres v. United States. 340 U. S. 135, distinguished. Pp. 150-166. 305 F. 2d 253, 285, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"United States v. Nordic Village , Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"sum":"After respondent Nordic Village, Inc., filed a petition for relief under Chapter 11 of the Bankruptcy Code, one of its officers withdrew funds from the company's corporate account. He sent part of the money to the Internal Revenue Service (IRS), directing it to apply the funds against his individual tax liability, which it did. In a subsequent adversary proceeding, the Bankruptcy Court permitted Nordic Village's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"United States v. Price","cite":"361 U.S. 304","y":1960,"id":"1959/48","sc":1,"sum":"Under § 272 (a) (1) of the Internal Revenue Code of 1939, as amended, failure of the Commissioner of Internal Revenue to send to a taxpayer a 90-day notice of a deficiency in his income tax return does not bar an action by the United States to collect such deficiency and statutory interest thereon when the taxpayer had executed and filed, under § 272 (d), a waiver of the restrictions of § 272 (a) on the assessment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"United States v. Riverside Bayview Homes, Inc.","cite":"474 U.S. 121","y":1985,"id":"1985/84-701","sc":1,"sum":"The Clean Water Act prohibits any discharge of dredged or fill materials into \"navigable waters\"-defined as the \"waters of the United States\"unless authorized by a permit issued by the Army Corps of Engineers (Corps). Construing the Act to cover all \"freshwater wetlands\" that are adjacent to other covered waters, the Corps issued a regulation defining such wetlands as \"those areas that are inundated or saturated by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"United States v. Smith","cite":"499 U.S. 160","y":1991,"id":"1990/89-1646","sc":1,"op":1,"sum":"Noting that interpre­ tive canons must yield “when the whole context dictates a different conclusion”.","sumSrc":"opinion","by":{"0":"42"}},{"t":"case","label":"United States v. Turkette","cite":"452 U.S. 576","y":1981,"id":"1980/80-808","sc":1,"sum":"The term \"enterprise\" as used in RICO encompasses both legitimate and illegitimate enterprises.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"United States v. 2,116 Boxes of Boned Beef","cite":"726 F.2d 1481","y":1984,"url":"https://www.courtlistener.com/c/F.2d/726/1481/","by":{"0":"11, 39"}},{"t":"case","label":"Vermont Agency of Natural Res. v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Washington State Dep’t of Soc. & Health Servs. v. Guardianship Estate of Keffeler","cite":"537 U.S. 371","y":2003,"id":"2002/01-1420","sc":1,"op":3,"sum":"The Court held that the state's use of the Social Security benefits to reimburse itself does not violate the Social Security Act's anti-attachment provision.","sumSrc":"Oyez","by":{"0":"20, 36"}},{"t":"case","label":"Watt v. Western Nuclear, Inc.","cite":"462 U.S. 36","y":1983,"id":"1982/81-1686","sc":1,"sum":"Gravel found on lands patented under the SRHA is a mineral reserved to the United States within the meaning of §9 of the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"West Virginia Univ. Hosp., Inc.. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"op":1,"sum":"Noting that interpre­ tive canons must yield “when the whole context dictates a different conclusion”.","sumSrc":"opinion","by":{"0":"13"}},{"t":"case","label":"Ysasi v. Rivkind","cite":"856 F.2d 1520","y":1988,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/856/1520/","op":1,"sum":"Concluding that “the government’s broad reading of [Section 2680(c)] comports with [Judge Holtzoff’s] report”.","sumSrc":"brief:0","by":{"0":"11, 33, 39"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"4"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"4"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"4"}},{"t":"law","label":"Pub. L. No. 93-253","url":"https://www.govinfo.gov/link/statute/88/50","by":{"0":"29"}},{"t":"law","label":"Pub. L. No. 106-185","url":"https://www.govinfo.gov/link/plaw/106/public/185","by":{"0":"10, 11, 28"}},{"t":"law","label":"Pub. L. No. 100-694","url":"https://www.govinfo.gov/link/statute/102/4563","by":{"0":"42"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(b)","(b)(1)"],"stext":{"head":"§1346. United States as defendant","paras":[[0,"(a) The district courts shall have original jurisdiction, concurrent with the United States Court of Federal Claims, of:"],[1,"(1) Any civil action against the United States for the recovery of any internal-revenue tax alleged to have been erroneously or illegally assessed or collected, or any penalty claimed to have been collected without authority or any sum alleged to have been excessive or in any manner wrongfully collected under the internal-revenue laws;"],[1,"(2) Any other civil action or claim against the United States, not exceeding $10,000 in amount, founded either upon the Constitution, or any Act of Congress, or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort, except that the district courts shall not have jurisdiction of any civil action or claim against the United States founded upon any express or implied contract with the United States or for liquidated or unliquidated damages in cases not sounding in tort which are subject to sections 7104(b)(1) and 7107(a)(1) of title 41. For the purpose of this paragraph, an express or implied contract with the Army and Air Force Exchange Service, Navy Exchanges, Marine Corps Exchanges, Coast Guard Exchanges, or Exchange Councils of the National Aeronautics and Space Administration shall be considered an express or implied contract with the United States."],[0,"(b)(1) Subject to the provisions of chapter 171 of this title, the district courts, together with the United States District Court for the District of the Canal Zone and the District Court of the Virgin Islands, shall have exclusive jurisdiction of civil actions on claims against the United States, for money damages, accruing on and after January 1, 1945, for injury or loss of property, or personal injury or death caused by the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment, under circumstances where the United States, if a private person, would be liable to the claimant in accordance with the law of the place where the act or omission occurred."],[0,"(2) No person convicted of a felony who is incarcerated while awaiting sentencing or while serving a sentence may bring a civil action against the United States or an agency, officer, or employee of the Government, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(c) The jurisdiction conferred by this section includes jurisdiction of any set-off, counterclaim, or other claim or demand whatever on the part of the United States against any plaintiff commencing an action under this section."],[0,"(d) The district courts shall not have jurisdiction under this section of any civil action or claim for a pension."],[0,"(e) The district courts shall have original jurisdiction of any civil action against the United States provided in section 6226, 6228(a), 7426, or 7428 (in the case of the United States district court for the District of Columbia) or section 7429 of the Internal Revenue Code of 1986."],[0,"(f) The district courts shall have exclusive original jurisdiction of civil actions under section 2409a to quiet title to an estate or interest in real property in which an interest is claimed by the United States."],[0,"(g) Subject to the provisions of chapter 179, the district courts of the United States shall have exclusive jurisdiction over any civil action commenced under section 453(2) of title 3, by a covered employee under chapter 5 of such title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1346?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1346. United States as defendant","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 2, 10"}},{"t":"usc","label":"28 U.S.C. § 2671","url":"https://www.law.cornell.edu/uscode/text/28/2671","by":{"0":"2"}},{"t":"usc","label":"28 U.S.C. § 2679","url":"https://www.law.cornell.edu/uscode/text/28/2679","subs":["(d)"],"by":{"0":"42"}},{"t":"usc","label":"28 U.S.C. § 2680","url":"https://www.law.cornell.edu/uscode/text/28/2680","subs":["(a)","(b)","(c)(1994)","(c)","(h)"],"stext":{"head":"§2680. Exceptions","paras":[[0,"The provisions of this chapter and section 1346(b) of this title shall not apply to—"],[0,"(a) Any claim based upon an act or omission of an employee of the Government, exercising due care, in the execution of a statute or regulation, whether or not such statute or regulation be valid, or based upon the exercise or performance or the failure to exercise or perform a discretionary function or duty on the part of a federal agency or an employee of the Government, whether or not the discretion involved be abused."],[0,"(b) Any claim arising out of the loss, miscarriage, or negligent transmission of letters or postal matter."],[0,"(c) Any claim arising in respect of the assessment or collection of any tax or customs duty, or the detention of any goods, merchandise, or other property by any officer of customs or excise or any other law enforcement officer, except that the provisions of this chapter and section 1346(b) of this title apply to any claim based on injury or loss of goods, merchandise, or other property, while in the possession of any officer of customs or excise or any other law enforcement officer, if—"],[1,"(1) the property was seized for the purpose of forfeiture under any provision of Federal law providing for the forfeiture of property other than as a sentence imposed upon conviction of a criminal offense;"],[1,"(2) the interest of the claimant was not forfeited;"],[1,"(3) the interest of the claimant was not remitted or mitigated (if the property was subject to forfeiture); and"],[1,"(4) the claimant was not convicted of a crime for which the interest of the claimant in the property was subject to forfeiture under a Federal criminal forfeiture law..1"],[0,"(d) Any claim for which a remedy is provided by chapter 309 or 311 of title 46 relating to claims or suits in admiralty against the United States."],[0,"(e) Any claim arising out of an act or omission of any employee of the Government in administering the provisions of sections 1–31 of Title 50, Appendix.2"],[0,"(f) Any claim for damages caused by the imposition or establishment of a quarantine by the United States."],[0,"[(g) Repealed. Sept. 26, 1950, ch. 1049, §13 (5), 64 Stat. 1043.]"],[0,"(h) Any claim arising out of assault, battery, false imprisonment, false arrest, malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights: Provided, That, with regard to acts or omissions of investigative or law enforcement officers of the United States Government, the provisions of this chapter and section 1346(b) of this title shall apply to any claim arising, on or after the date of the enactment of this proviso, out of assault, battery, false imprisonment, false arrest, abuse of process, or malicious prosecution. For the purpose of this subsection, \"investigative or law enforcement officer\" means any officer of the United States who is empowered by law to execute searches, to seize evidence, or to make arrests for violations of Federal law."],[0,"(i) Any claim for damages caused by the fiscal operations of the Treasury or by the regulation of the monetary system."],[0,"(j) Any claim arising out of the combatant activities of the military or naval forces, or the Coast Guard, during time of war."],[0,"(k) Any claim arising in a foreign country."],[0,"(l) Any claim arising from the activities of the Tennessee Valley Authority."],[0,"(m) Any claim arising from the activities of the Panama Canal Company."],[0,"(n) Any claim arising from the activities of a Federal land bank, a Federal intermediate credit bank, or a bank for cooperatives."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2680?type=usc&year=mostrecent&link-type=html"},"op":13,"head":"§2680. Exceptions","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 2, 2, 11, passim, 2, 15, 28, 29"}},{"t":"usc","label":"48 U.S.C. § 1422","url":"https://www.law.cornell.edu/uscode/text/48/1422","stext":{"head":"§1422. Governor and Lieutenant Governor; term of office; qualifications; powers and duties; annual report to Congress","paras":[[0,"The executive power of Guam shall be vested in an executive officer whose official title shall be the \"Governor of Guam\". The Governor of Guam, together with the Lieutenant Governor, shall be elected by a majority of the votes cast by the people who are qualified to vote for the members of the Legislature of Guam. The Governor and Lieutenant Governor shall be chosen jointly, by the casting by each voter of a single vote applicable to both offices. If no candidates receive a majority of the votes cast in any election, on the fourteenth day thereafter a runoff election shall be held between the candidates for Governor and Lieutenant Governor receiving the highest and second highest number of votes cast. The first election for Governor and Lieutenant Governor shall be held on November 3, 1970. Thereafter, beginning with the year 1974, the Governor and Lieutenant Governor shall be elected every four years at the general election. The Governor and Lieutenant Governor shall hold office for a term of four years and until their successors are elected and qualified."],[0,"No person who has been elected Governor for two full successive terms shall again be eligible to hold that office until one full term has intervened."],[0,"The term of the elected Governor and Lieutenant Governor shall commence on the first Monday of January following the date of election."],[0,"No person shall be eligible for election to the office of Governor or Lieutenant Governor unless he is an eligible voter and has been for five consecutive years immediately preceding the election a citizen of the United States and a bona fide resident of Guam and will be, at the time of taking office, at least thirty years of age. The Governor shall maintain his official residence in Guam during his incumbency."],[0,"The Governor shall have general supervision and control of all the departments, bureaus, agencies, and other instrumentalities of the executive branch of the government of Guam. He may grant pardons and reprieves and remit fines and forfeitures for offenses against local laws. He may veto any legislation as provided in this chapter. He shall appoint, and may remove, all officers and employees of the executive branch of the government of Guam, except as otherwise provided in this or any other Act of Congress, or under the laws of Guam, and shall commission all officers that he may be authorized to appoint. He shall be responsible for the faithful execution of the laws of Guam and the laws of the United States applicable in Guam. Whenever it becomes necessary, in case of disaster, invasion, insurrection, or rebellion, or imminent danger thereof, or to prevent or suppress lawless violence, he may summon the posse comitatus or call out the militia or request assistance of the senior military or naval commander of the Armed Forces of the United States in Guam, which may be given at the discretion of such commander if not disruptive of, or inconsistent with, his Federal responsibilities. He may, in case of rebellion or invasion, or imminent danger thereof, when the public safety requires it, proclaim the island, insofar as it is under the jurisdiction of the government of Guam, to be under martial law. The members of the legislature shall meet forthwith on their own initiative and may, by a two-thirds vote, revoke such proclamation."],[0,"The Governor shall prepare, publish, and submit to the Congress and the Secretary of the Interior a comprehensive annual financial report in conformance with the standards of the National Council on Governmental Accounting within one hundred and twenty days after the close of the fiscal year. The comprehensive annual financial report shall include statistical data as set forth in the standards of the National Council on Governmental Accounting relating to the physical, economic, social, and political characteristics of the government, and any other information required by the Congress. The Governor shall also make such other reports at such other times as may be required by the Congress or under applicable Federal law. He shall have the power to issue executive orders and regulations not in conflict with any applicable law. He may recommend bills to the legislature and give expression to his views on any matter before that body."],[0,"There is hereby established the office of Lieutenant Governor of Guam. The Lieutenant Governor shall have such executive powers and perform such duties as may be assigned to him by the Governor or prescribed by this chapter or under the laws of Guam."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/48/1422?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1422. Governor and Lieutenant Governor; term of office; qualifications; powers and duties; annual report to Congress","tname":"Territories and Insular Possessions","by":{"0":"23"}},{"t":"usc","label":"42 U.S.C. § 1997e","url":"https://www.law.cornell.edu/uscode/text/42/1997e","subs":["(a)"],"stext":{"head":"§1997e. Suits by prisoners","paras":[[0,"(a) Applicability of administrative remedies"],[0,"No action shall be brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility until such administrative remedies as are available are exhausted."],[0,"(b) Failure of State to adopt or adhere to administrative grievance procedure"],[0,"The failure of a State to adopt or adhere to an administrative grievance procedure shall not constitute the basis for an action under section 1997a or 1997c of this title."],[0,"(c) Dismissal"],[0,"(1) The court shall on its own motion or on the motion of a party dismiss any action brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility if the court is satisfied that the action is frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief."],[0,"(2) In the event that a claim is, on its face, frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief, the court may dismiss the underlying claim without first requiring the exhaustion of administrative remedies."],[0,"(d) Attorney's fees"],[0,"(1) In any action brought by a prisoner who is confined to any jail, prison, or other correctional facility, in which attorney's fees are authorized under section 1988 1 of this title, such fees shall not be awarded, except to the extent that—"],[1,"(A) the fee was directly and reasonably incurred in proving an actual violation of the plaintiff's rights protected by a statute pursuant to which a fee may be awarded under section 1988 1 of this title; and"],[1,"(B)(i) the amount of the fee is proportionately related to the court ordered relief for the violation; or"],[1,"(ii) the fee was directly and reasonably incurred in enforcing the relief ordered for the violation."],[0,"(2) Whenever a monetary judgment is awarded in an action described in paragraph (1), a portion of the judgment (not to exceed 25 percent) shall be applied to satisfy the amount of attorney's fees awarded against the defendant. If the award of attorney's fees is not greater than 150 percent of the judgment, the excess shall be paid by the defendant."],[0,"(3) No award of attorney's fees in an action described in paragraph (1) shall be based on an hourly rate greater than 150 percent of the hourly rate established under section 3006A of title 18 for payment of court-appointed counsel."],[0,"(4) Nothing in this subsection shall prohibit a prisoner from entering into an agreement to pay an attorney's fee in an amount greater than the amount authorized under this subsection, if the fee is paid by the individual rather than by the defendant pursuant to section 1988 1 of this title."],[0,"(e) Limitation on recovery"],[0,"No Federal civil action may be brought by a prisoner confined in a jail, prison, or other correctional facility, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(f) Hearings"],[0,"(1) To the extent practicable, in any action brought with respect to prison conditions in Federal court pursuant to section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility, pretrial proceedings in which the prisoner's participation is required or permitted shall be conducted by telephone, video conference, or other telecommunications technology without removing the prisoner from the facility in which the prisoner is confined."],[0,"(2) Subject to the agreement of the official of the Federal, State, or local unit of government with custody over the prisoner, hearings may be conducted at the facility in which the prisoner is confined. To the extent practicable, the court shall allow counsel to participate by telephone, video conference, or other communications technology in any hearing held at the facility."],[0,"(g) Waiver of reply"],[0,"(1) Any defendant may waive the right to reply to any action brought by a prisoner confined in any jail, prison, or other correctional facility under section 1983 of this title or any other Federal law. Notwithstanding any other law or rule of procedure, such waiver shall not constitute an admission of the allegations contained in the complaint. No relief shall be granted to the plaintiff unless a reply has been filed."],[0,"(2) The court may require any defendant to reply to a complaint brought under this section if it finds that the plaintiff has a reasonable opportunity to prevail on the merits."],[0,"(h) \"Prisoner\" defined"],[0,"As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1997e?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1997e. Suits by prisoners","tname":"The Public Health and Welfare","by":{"0":"40, 4"}},{"t":"usc","label":"42 U.S.C. § 2000bb","url":"https://www.law.cornell.edu/uscode/text/42/2000bb","by":{"0":"4"}},{"t":"usc","label":"42 U.S.C. § 2000cc","url":"https://www.law.cornell.edu/uscode/text/42/2000cc","by":{"0":"4"}},{"t":"usc","label":"5 U.S.C. § 8331","url":"https://www.law.cornell.edu/uscode/text/5/8331","subs":["(20)"],"by":{"0":"15"}},{"t":"usc","label":"18 U.S.C. § 758","url":"https://www.law.cornell.edu/uscode/text/18/758","by":{"0":"26"}},{"t":"usc","label":"18 U.S.C. § 2113","url":"https://www.law.cornell.edu/uscode/text/18/2113","subs":["(a)"],"by":{"0":"26"}},{"t":"usc","label":"18 U.S.C. § 3050","url":"https://www.law.cornell.edu/uscode/text/18/3050","by":{"0":"15"}},{"t":"usc","label":"18 U.S.C. § 3592","url":"https://www.law.cornell.edu/uscode/text/18/3592","subs":["(c)(14)(D)"],"by":{"0":"15"}},{"t":"usc","label":"18 U.S.C. § 1401","url":"https://www.law.cornell.edu/uscode/text/18/1401","subs":["(i)"],"by":{"0":"19"}},{"t":"usc","label":"19 U.S.C. § 482","url":"https://www.law.cornell.edu/uscode/text/19/482","by":{"0":"25"}},{"t":"usc","label":"19 U.S.C. § 1589a","url":"https://www.law.cornell.edu/uscode/text/19/1589a","by":{"0":"19"}},{"t":"usc","label":"19 U.S.C. § 1595a","url":"https://www.law.cornell.edu/uscode/text/19/1595a","stext":{"head":"§1595a. Aiding unlawful importation","paras":[[0,"(a) Importation, removal, etc. contrary to laws of United States"],[0,"Except as specified in subsection (b) or (c) of section 1594 of this title, every vessel, vehicle, animal, aircraft, or other thing used in, to aid in, or to facilitate, by obtaining information or in any other way, the importation, bringing in, unlading, landing, removal, concealing, harboring, or subsequent transportation of any article which is being or has been introduced, or attempted to be introduced, into the United States contrary to law, whether upon such vessel, vehicle, animal, aircraft, or other thing or otherwise, may be seized and forfeited together with its tackle, apparel, furniture, harness, or equipment."],[0,"(b) Penalty for aiding unlawful importation"],[0,"Every person who directs, assists financially or otherwise, or is in any way concerned in any unlawful activity mentioned in the preceding subsection shall be liable to a penalty equal to the value of the article or articles introduced or attempted to be introduced."],[0,"(c) Merchandise introduced contrary to law"],[0,"Merchandise which is introduced or attempted to be introduced into the United States contrary to law shall be treated as follows:"],[1,"(1) The merchandise shall be seized and forfeited if it—"],[2,"(A) is stolen, smuggled, or clandestinely imported or introduced;"],[2,"(B) is a controlled substance, as defined in the Controlled Substances Act (21 U.S.C. 801 et seq.), and is not imported in accordance with applicable law;"],[2,"(C) is a contraband article, as defined in section 80302 of title 49; or"],[2,"(D) is a plastic explosive, as defined in section 841(q) of title 18, which does not contain a detection agent, as defined in section 841(p) of such title."],[1,"(2) The merchandise may be seized and forfeited if—"],[2,"(A) its importation or entry is subject to any restriction or prohibition which is imposed by law relating to health, safety, or conservation and the merchandise is not in compliance with the applicable rule, regulation, or statute;"],[2,"(B) its importation or entry requires a license, permit or other authorization of an agency of the United States Government and the merchandise is not accompanied by such license, permit, or authorization;"],[2,"(C) it is merchandise or packaging in which copyright, trademark, or trade name protection violations are involved (including, but not limited to, violations of section 1124, 1125, or 1127 of title 15, section 506 of title 17, or section 2318 or 2320 of title 18);"],[2,"(D) it is trade dress merchandise involved in the violation of a court order citing section 1125 of title 15;"],[2,"(E) it is merchandise which is marked intentionally in violation of section 1304 of this title;"],[2,"(F) it is merchandise for which the importer has received written notices that previous importations of identical merchandise from the same supplier were found to have been marked in violation of section 1304 of this title; or"],[2,"(G) U.S. Customs and Border Protection determines it is a technology, product, service, device, component, or part thereof the importation of which is prohibited under subsection (a)(2) or (b)(1) of section 1201 of title 17."],[1,"(3) If the importation or entry of the merchandise is subject to quantitative restrictions requiring a visa, permit, license, or other similar document, or stamp from the United States Government or from a foreign government or issuing authority pursuant to a bilateral or multilateral agreement, the merchandise shall be subject to detention in accordance with section 1499 of this title unless the appropriate visa, license, permit, or similar document or stamp is presented to the Customs Service; but if the visa, permit, license, or similar document or stamp which is presented in connection with the importation or entry of the merchandise is counterfeit, the merchandise may be seized and forfeited."],[1,"(4) If the merchandise is imported or introduced contrary to a provision of law which governs the classification or value of merchandise and there are no issues as to the admissibility of the merchandise into the United States, it shall not be seized except in accordance with section 1592 of this title."],[1,"(5) In any case where the seizure and forfeiture of merchandise are required or authorized by this section, the Secretary may—"],[2,"(A) remit the forfeiture under section 1618 of this title, or"],[2,"(B) permit the exportation of the merchandise, unless its release would adversely affect health, safety, or conservation or be in contravention of a bilateral or multilateral agreement or treaty."],[0,"(d) Merchandise exported contrary to law"],[0,"Merchandise exported or sent from the United States or attempted to be exported or sent from the United States contrary to law, or the proceeds or value thereof, and property used to facilitate the exporting or sending of such merchandise, the attempted exporting or sending of such merchandise, or the receipt, purchase, transportation, concealment, or sale of such merchandise prior to exportation shall be seized and forfeited to the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/19/1595a?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1595a. Aiding unlawful importation","tname":"Customs Duties","by":{"0":"12"}},{"t":"usc","label":"20 U.S.C. § 1652","url":"https://www.law.cornell.edu/uscode/text/20/1652","subs":["(b)"],"by":{"0":"26"}},{"t":"usc","label":"21 U.S.C. § 878","url":"https://www.law.cornell.edu/uscode/text/21/878","by":{"0":"25"}},{"t":"usc","label":"21 U.S.C. § 881","url":"https://www.law.cornell.edu/uscode/text/21/881","subs":["(a)(4)","(b)"],"stext":{"head":"§881. Forfeitures","paras":[[0,"(a) Subject property"],[0,"The following shall be subject to forfeiture to the United States and no property right shall exist in them:"],[1,"(1) All controlled substances which have been manufactured, distributed, dispensed, or acquired in violation of this subchapter."],[1,"(2) All raw materials, products, and equipment of any kind which are used, or intended for use, in manufacturing, compounding, processing, delivering, importing, or exporting any controlled substance or listed chemical in violation of this subchapter."],[1,"(3) All property which is used, or intended for use, as a container for property described in paragraph (1), (2), or (9)."],[1,"(4) All conveyances, including aircraft, vehicles, or vessels, which are used, or are intended for use, to transport, or in any manner to facilitate the transportation, sale, receipt, possession, or concealment of property described in paragraph (1), (2), or (9)."],[1,"(5) All books, records, and research, including formulas, microfilm, tapes, and data which are used, or intended for use, in violation of this subchapter."],[1,"(6) All moneys, negotiable instruments, securities, or other things of value furnished or intended to be furnished by any person in exchange for a controlled substance or listed chemical in violation of this subchapter, all proceeds traceable to such an exchange, and all moneys, negotiable instruments, and securities used or intended to be used to facilitate any violation of this subchapter."],[1,"(7) All real property, including any right, title, and interest (including any leasehold interest) in the whole of any lot or tract of land and any appurtenances or improvements, which is used, or intended to be used, in any manner or part, to commit, or to facilitate the commission of, a violation of this subchapter punishable by more than one year's imprisonment."],[1,"(8) All controlled substances which have been possessed in violation of this subchapter."],[1,"(9) All listed chemicals, all drug manufacturing equipment, all tableting machines, all encapsulating machines, and all gelatin capsules, which have been imported, exported, manufactured, possessed, distributed, dispensed, acquired, or intended to be distributed, dispensed, acquired, imported, or exported, in violation of this subchapter or subchapter II."],[1,"(10) Any drug paraphernalia (as defined in section 863 of this title)."],[1,"(11) Any firearm (as defined in section 921 of title 18) used or intended to be used to facilitate the transportation, sale, receipt, possession, or concealment of property described in paragraph (1) or (2) and any proceeds traceable to such property."],[0,"(b) Seizure procedures"],[0,"Any property subject to forfeiture to the United States under this section may be seized by the Attorney General in the manner set forth in section 981(b) of title 18."],[0,"(c) Custody of Attorney General"],[0,"Property taken or detained under this section shall not be repleviable, but shall be deemed to be in the custody of the Attorney General, subject only to the orders and decrees of the court or the official having jurisdiction thereof. Whenever property is seized under any of the provisions of this subchapter, the Attorney General may—"],[1,"(1) place the property under seal;"],[1,"(2) remove the property to a place designated by him; or"],[1,"(3) require that the General Services Administration take custody of the property and remove it, if practicable, to an appropriate location for disposition in accordance with law."],[0,"(d) Other laws and proceedings applicable"],[0,"The provisions of law relating to the seizure, summary and judicial forfeiture, and condemnation of property for violation of the customs laws; the disposition of such property or the proceeds from the sale thereof; the remission or mitigation of such forfeitures; and the compromise of claims shall apply to seizures and forfeitures incurred, or alleged to have been incurred, under any of the provisions of this subchapter, insofar as applicable and not inconsistent with the provisions hereof; except that such duties as are imposed upon the customs officer or any other person with respect to the seizure and forfeiture of property under the customs laws shall be performed with respect to seizures and forfeitures of property under this subchapter by such officers, agents, or other persons as may be authorized or designated for that purpose by the Attorney General, except to the extent that such duties arise from seizures and forfeitures effected by any customs officer."],[0,"(e) Disposition of forfeited property"],[0,"(1) Whenever property is civilly or criminally forfeited under this subchapter the Attorney General may—"],[1,"(A) retain the property for official use or, in the manner provided with respect to transfers under section 1616a of title 19, transfer the property to any Federal agency or to any State or local law enforcement agency which participated directly in the seizure or forfeiture of the property;"],[1,"(B) except as provided in paragraph (4), sell, by public sale or any other commercially feasible means, any forfeited property which is not required to be destroyed by law and which is not harmful to the public;"],[1,"(C) require that the General Services Administration take custody of the property and dispose of it in accordance with law;"],[1,"(D) forward it to the Bureau of Narcotics and Dangerous Drugs for disposition (including delivery for medical or scientific use to any Federal or State agency under regulations of the Attorney General); or"],[1,"(E) transfer the forfeited personal property or the proceeds of the sale of any forfeited personal or real property to any foreign country which participated directly or indirectly in the seizure or forfeiture of the property, if such a transfer—"],[2,"(i) has been agreed to by the Secretary of State;"],[2,"(ii) is authorized in an international agreement between the United States and the foreign country; and"],[2,"(iii) is made to a country which, if applicable, has been certified under section 2291j(b) of title 22."],[0,"(2)(A) The proceeds from any sale under subparagraph (B) of paragraph (1) and any moneys forfeited under this subchapter shall be used to pay—"],[1,"(i) all property expenses of the proceedings for forfeiture and sale including expenses of seizure, maintenance of custody, advertising, and court costs; and"],[1,"(ii) awards of up to $100,000 to any individual who provides original information which leads to the arrest and conviction of a person who kills or kidnaps a Federal drug law enforcement agent."],[0,"Any award paid for information concerning the killing or kidnapping of a Federal drug law enforcement agent, as provided in clause (ii), shall be paid at the discretion of the Attorney General."],[0,"(B) The Attorney General shall forward to the Treasurer of the United States for deposit in accordance with section 524(c) of title 28, any amounts of such moneys and proceeds remaining after payment of the expenses provided in subparagraph (A), except that, with respect to forfeitures conducted by the Postal Service, the Postal Service shall deposit in the Postal Service Fund, under section 2003(b)(7) of title 39, such moneys and proceeds."],[0,"(3) The Attorney General shall assure that any property transferred to a State or local law enforcement agency under paragraph (1)(A)—"],[1,"(A) has a value that bears a reasonable relationship to the degree of direct participation of the State or local agency in the law enforcement effort resulting in the forfeiture, taking into account the total value of all property forfeited and the total law enforcement effort with respect to the violation of law on which the forfeiture is based; and"],[1,"(B) will serve to encourage further cooperation between the recipient State or local agency and Federal law enforcement agencies."],[0,"(4)(A) With respect to real property described in subparagraph (B), if the chief executive officer of the State involved submits to the Attorney General a request for purposes of such subparagraph, the authority established in such subparagraph is in lieu of the authority established in paragraph (1)(B)."],[0,"(B) In the case of property described in paragraph (1)(B) that is civilly or criminally forfeited under this subchapter, if the property is real property that is appropriate for use as a public area reserved for recreational or historic purposes or for the preservation of natural conditions, the Attorney General, upon the request of the chief executive officer of the State in which the property is located, may transfer title to the property to the State, either without charge or for a nominal charge, through a legal instrument providing that—"],[1,"(i) such use will be the principal use of the property; and"],[1,"(ii) title to the property reverts to the United States in the event that the property is used otherwise."],[0,"(f) Forfeiture and destruction of schedule I and II substances"],[0,"(1) All controlled substances in schedule I or II that are possessed, transferred, sold, or offered for sale in violation of the provisions of this subchapter; all dangerous, toxic, or hazardous raw materials or products subject to forfeiture under subsection (a)(2) of this section; and any equipment or container subject to forfeiture under subsection (a)(2) or (3) which cannot be separated safely from such raw materials or products shall be deemed contraband and seized and summarily forfeited to the United States. Similarly, all substances in schedule I or II, which are seized or come into the possession of the United States, the owners of which are unknown, shall be deemed contraband and summarily forfeited to the United States."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/881?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§881. Forfeitures","tname":"Food and Drugs","by":{"0":"25, 25"}},{"t":"usc","label":"21 U.S.C. § 952","url":"https://www.law.cornell.edu/uscode/text/21/952","by":{"0":"25"}},{"t":"usc","label":"26 U.S.C. § 7301","url":"https://www.law.cornell.edu/uscode/text/26/7301","by":{"0":"12"}},{"t":"usc","label":"26 U.S.C. § 7608","url":"https://www.law.cornell.edu/uscode/text/26/7608","by":{"0":"19"}},{"t":"usc","label":"28 U.S.C. § 1442","url":"https://www.law.cornell.edu/uscode/text/28/1442","subs":["(a)"],"by":{"0":"41"}},{"t":"usc","label":"28 U.S.C. § 2006","url":"https://www.law.cornell.edu/uscode/text/28/2006","by":{"0":"42"}},{"t":"usc","label":"31 U.S.C. § 3723","url":"https://www.law.cornell.edu/uscode/text/31/3723","stext":{"head":"§3723. Small claims for privately owned property damage or loss","paras":[[0,"(a) The head of an agency (except a military department of the Department of Defense or the Coast Guard) may settle a claim for not more than $1,000 for damage to, or loss of, privately owned property that—"],[1,"(1) is caused by the negligence of an officer or employee of the United States Government acting within the scope of employment; and"],[1,"(2) may not be settled under chapter 171 of title 28."],[0,"(b) A claim under this section may be allowed only if it is presented to the head of the agency within one year after it accrues."],[0,"(c) A claim under this section may be paid as provided in section 1304 of this title only if the claimant accepts the amount of the settlement in complete satisfaction of the claim against the Government."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3723?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§3723. Small claims for privately owned property damage or loss","tname":"Money and Finance","by":{"0":"41"}},{"t":"usc","label":"42 U.S.C. § 407","url":"https://www.law.cornell.edu/uscode/text/42/407","subs":["(a)"],"stext":{"head":"§407. Assignment of benefits","paras":[[0,"(a) In general"],[0,"The right of any person to any future payment under this subchapter shall not be transferable or assignable, at law or in equity, and none of the moneys paid or payable or rights existing under this subchapter shall be subject to execution, levy, attachment, garnishment, or other legal process, or to the operation of any bankruptcy or insolvency law."],[0,"(b) Amendment of section"],[0,"No other provision of law, enacted before, on, or after April 20, 1983, may be construed to limit, supersede, or otherwise modify the provisions of this section except to the extent that it does so by express reference to this section."],[0,"(c) Withholding of taxes"],[0,"Nothing in this section shall be construed to prohibit withholding taxes from any benefit under this subchapter, if such withholding is done pursuant to a request made in accordance with section 3402(p)(1) of the Internal Revenue Code of 1986 by the person entitled to such benefit or such person's representative payee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/407?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§407. Assignment of benefits","tname":"The Public Health and Welfare","by":{"0":"20"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"17"}},{"t":"usc","label":"42 U.S.C. § 3796b","url":"https://www.law.cornell.edu/uscode/text/42/3796b","subs":["(6)"],"by":{"0":"15"}},{"t":"reg","label":"28 C.F.R. § 543.30-543","url":"https://www.ecfr.gov/current/title-28/section-543.30-543","by":{"0":"3"}}]};